/* From Uiverse.io by andrew-demchenk0 - Tags: alert, blue, card, message, info, close, info message */
.__UIV_SCOPE__ .info {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  width: 320px;
  padding: 12px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: start;
  background: #509AF8;
  border-radius: 8px;
  box-shadow: 0px 0px 5px -3px #111;
}

.__UIV_SCOPE__ .info__icon {
  width: 20px;
  height: 20px;
  transform: translateY(-2px);
  margin-right: 8px;
}

.__UIV_SCOPE__ .info__icon path {
  fill: #fff;
}

.__UIV_SCOPE__ .info__title {
  font-weight: 500;
  font-size: 14px;
  color: #fff;
}

.__UIV_SCOPE__ .info__close {
  width: 20px;
  height: 20px;
  cursor: pointer;
  margin-left: auto;
}

.__UIV_SCOPE__ .info__close path {
  fill: #fff;
}
